#!/usr/bin/env python3
"""Decode authenticated NPV Tunnel NPVS v5 app-key files (124.0.37).

Dependency: python -m pip install pycryptodome
Usage: python npvs.py INPUT.npvs -o decoded.json
The embedded white-box tables are application data, not sample-specific keys.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import hmac
import json
import struct
import sys
import zlib
from functools import lru_cache
from pathlib import Path

from Crypto.Cipher import ChaCha20_Poly1305
from Crypto.Hash import SHA256
from Crypto.Protocol.KDF import HKDF
from Crypto.PublicKey import ECC
from Crypto.Signature import DSS

_TABLE_HASH = "35717e8267a115fbf474e3cd622066783feea21305457c840cabd57a73086f7d"
_SHIFT_ROWS = (0, 5, 10, 15, 4, 9, 14, 3, 8, 13, 2, 7, 12, 1, 6, 11)
_MAX_FILE = 4 * 1024 * 1024


class DecodeError(ValueError):
    """Invalid, unauthenticated, or unsupported NPVS input."""


def _json_load(data: bytes):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise DecodeError("Duplicate JSON key")
            result[key] = value
        return result

    def invalid_constant(value):
        raise DecodeError("Invalid JSON number")

    try:
        return json.loads(data.decode("utf-8"), object_pairs_hook=pairs,
                          parse_constant=invalid_constant)
    except (UnicodeError, json.JSONDecodeError, RecursionError) as exc:
        raise DecodeError("Invalid UTF-8 JSON") from exc


def _canonical(value) -> bytes:
    text = json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False)
    for char, escaped in (("<", "\\u003c"), (">", "\\u003e"), ("&", "\\u0026"),
                          ("\u2028", "\\u2028"), ("\u2029", "\\u2029")):
        text = text.replace(char, escaped)
    return text.encode("utf-8")


@lru_cache(maxsize=1)
def _tables() -> bytes:
    raw = zlib.decompress(base64.b85decode(_TABLE_DATA))
    if len(raw) != 749569 or hashlib.sha256(raw).hexdigest() != _TABLE_HASH:
        raise DecodeError("Embedded application tables are damaged")
    return raw


def _whitebox_block(block: bytes) -> bytes:
    """The APK's 14-round, two-stage white-box AES evaluator."""
    if len(block) != 16:
        raise DecodeError("White-box input must have 16 bytes")
    table = _tables()
    rounds = table[0] - 1
    first = 1 + rounds * 24576
    final = first + rounds * 16384
    second = final + 4096
    state = list(block)

    def combine(values, round_index, word_tables):
        output = [0] * 16
        for col in range(4):
            words = []
            for i in range(4):
                index = col * 4 + i
                offset = word_tables + round_index * 16384 + index * 1024 + values[index] * 4
                words.append(int.from_bytes(table[offset:offset + 4], "big"))
            for row in range(4):
                start = 1 + round_index * 24576 + (col * 24 + row * 6) * 256

                def pair(offset, a, b, shift):
                    return table[start + offset * 256 + ((words[a] >> shift) & 15) * 16
                                 + ((words[b] >> shift) & 15)]

                high = table[start + 1024 + pair(0, 0, 1, 28 - 8 * row) * 16
                             + pair(1, 2, 3, 28 - 8 * row)]
                low = table[start + 1280 + pair(2, 0, 1, 24 - 8 * row) * 16
                            + pair(3, 2, 3, 24 - 8 * row)]
                output[col * 4 + row] = (high << 4) | low
        return output

    for r in range(rounds):
        state = [state[i] for i in _SHIFT_ROWS]
        state = combine(state, r, first)
        state = combine(state, r, second)
    state = [state[i] for i in _SHIFT_ROWS]
    return bytes(table[final + i * 256 + state[i]] for i in range(16))


def _open(key: bytes, nonce: bytes, data: bytes, aad: bytes, label: str) -> bytes:
    if len(data) < 16:
        raise DecodeError(f"Truncated {label}")
    try:
        cipher = ChaCha20_Poly1305.new(key=key, nonce=nonce)
        cipher.update(aad)
        return cipher.decrypt_and_verify(data[:-16], data[-16:])
    except ValueError as exc:
        raise DecodeError(f"Authentication failed: {label}") from exc


def _signature(data: bytes, public_key: bytes):
    try:
        key = ECC.import_key(public_key, curve_name="P-256")
        DSS.new(key, "fips-186-3", encoding="binary").verify(
            SHA256.new(data[:-64]), data[-64:])
    except (ValueError, TypeError, IndexError) as exc:
        raise DecodeError("Invalid NPVS ECDSA signature") from exc


def _field_key(dek: bytes, context: bytes, label: bytes, field_id: int) -> bytes:
    return HKDF(dek, 32, context, SHA256,
                context=b"NPV-fields-v1/" + label + b"/" + struct.pack(">H", field_id))


def _document(body: bytes, dek: bytes, context: bytes):
    if len(body) < 70 or body[:4] != b"NPF\x01" or body[4:36] != context:
        raise DecodeError("Invalid field container or metadata binding")
    expected = hmac.new(_field_key(dek, context, b"inventory", 0),
                        body[:-32], hashlib.sha256).digest()
    if not hmac.compare_digest(expected, body[-32:]):
        raise DecodeError("Invalid field inventory HMAC")
    count = int.from_bytes(body[36:38], "big")
    if not count:
        raise DecodeError("Empty field inventory")
    pos, last_id, records = 38, 0, {}
    for _ in range(count):
        if pos + 6 > len(body) - 32:
            raise DecodeError("Truncated field record")
        field_id, length = struct.unpack_from(">HI", body, pos)
        pos += 6
        if field_id <= last_id or not 16 <= length <= 1048592 or pos + length > len(body) - 32:
            raise DecodeError("Invalid field record bounds or ordering")
        payload = body[pos:pos + length]
        pos += length
        aad = b"NPV-fields-v1/record/" + context + struct.pack(">HI", field_id, length - 16)
        plain = _open(_field_key(dek, context, b"field", field_id), bytes(12),
                      payload, aad, f"field {field_id}")
        records[field_id] = _json_load(plain)
        last_id = field_id
    if pos != len(body) - 32 or 65535 not in records:
        raise DecodeError("Invalid field layout or trailing bytes")
    used = set()

    def resolve(node, depth=0):
        if depth > 128:
            raise DecodeError("Field layout is too deep")
        if isinstance(node, dict):
            return {k: resolve(v, depth + 1) for k, v in node.items()}
        if isinstance(node, list):
            return [resolve(v, depth + 1) for v in node]
        if type(node) is not int or not 1 <= node < 65535 or node not in records:
            raise DecodeError("Invalid scalar reference in field layout")
        value = records[node]
        if isinstance(value, (dict, list)):
            raise DecodeError("Field scalar contains a container")
        used.add(node)
        return value

    document = resolve(records[65535])
    if used != set(records) - {65535}:
        raise DecodeError("Unreferenced configuration fields")
    if not isinstance(document, dict) or not isinstance(document.get("configs"), list):
        raise DecodeError("Configuration document has no configs array")
    return document


def decode_npvs(data: bytes) -> dict:
    """Authenticate and decode a v5 app-key envelope; retain its policy metadata."""
    if not isinstance(data, bytes) or not 89 <= len(data) <= _MAX_FILE:
        raise DecodeError("Invalid NPVS file size")
    if data[:4] != b"NPVS":
        raise DecodeError("Expected binary NPVS input")
    if data[4] != 5:
        raise DecodeError("Only NPVS version 5 is supported")
    hlen = int.from_bytes(data[5:9], "big")
    if not 135 <= hlen <= 262144 or 9 + hlen + 80 > len(data):
        raise DecodeError("Invalid compact header length")
    header = data[9:9 + hlen]
    if header[0] != 1 or header[50] != 2:
        raise DecodeError("Only compact app-key configurations are supported")
    recipients = int.from_bytes(header[51:53], "big")
    if recipients > 1024:
        raise DecodeError("Too many recipients")
    offset = 53 + recipients * 125
    if offset + 82 > len(header) or header[offset:offset + 2] != b"\x00\x02":
        raise DecodeError("Invalid app-key descriptor")
    salt = header[offset + 2:offset + 18]
    wrapped = header[offset + 18:offset + 78]
    prefix_end = offset + 78
    mlen = int.from_bytes(header[prefix_end:prefix_end + 4], "big")
    if mlen < 16 or prefix_end + 4 + mlen != hlen:
        raise DecodeError("Invalid metadata length")
    end = 9 + hlen
    nonce = data[end:end + 12]
    blen = int.from_bytes(data[end + 12:end + 16], "big")
    if blen < 70 or end + 16 + blen + 64 != len(data):
        raise DecodeError("Invalid body length or trailing bytes")
    public_key = header[17:50]
    _signature(data, public_key)
    config_id = header[1:17]
    kdk = hashlib.sha256(b"npvtunnel/appkey/v2 " + _whitebox_block(salt) + config_id).digest()
    dek = _open(kdk, wrapped[:12], wrapped[12:], salt, "document key")
    if len(dek) != 32:
        raise DecodeError("Invalid document key length")
    mkey = HKDF(dek, 32, nonce, SHA256, context=b"NPVS-v5/metadata")
    metadata = _json_load(_open(mkey, nonce, header[prefix_end + 4:],
                                header[:prefix_end], "metadata"))
    if not isinstance(metadata, dict) or not isinstance(metadata.get("policy"), dict):
        raise DecodeError("Invalid metadata structure")
    policy = metadata["policy"]
    source_policy = {
        "onlyMobileNetwork": policy.get("onlyMobileNetwork", False),
        "attestationLevel": policy.get("attestationLevel", ""),
        "expiresAt": policy.get("expiresAt"),
        "displayMessage": policy.get("displayMessage", ""),
        "customServerMessage": policy.get("customServerMessage", ""),
    }
    if policy.get("configVersion", 0):
        source_policy["configVersion"] = policy["configVersion"]
    encode = lambda b: base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")
    source_header = {
        "v": 5, "configId": encode(config_id), "issuedAt": metadata.get("issuedAt", ""),
        "creator": {"fp": encode(hashlib.sha256(public_key).digest()), "pk": encode(public_key)},
        "policy": source_policy, "recipients": None,
    }
    context = hashlib.sha256(b"NPVS-v5/source-fields-v1/" + _canonical(source_header) + nonce).digest()
    document = _document(data[end + 16:-64], dek, context)
    return {"metadata": metadata, "document": document}


def run(file_bytes: bytes) -> str:
    """SP-DECODE-compatible entry point; failures raise DecodeError."""
    return json.dumps(decode_npvs(file_bytes), ensure_ascii=False, indent=2, allow_nan=False)


def main() -> int:
    parser = argparse.ArgumentParser(description="Descifra archivos NPVS v5 de NPV Tunnel.")
    parser.add_argument("input", type=Path)
    parser.add_argument("-o", "--output", type=Path, help="Guarda el JSON descifrado")
    args = parser.parse_args()
    try:
        if args.input.stat().st_size > _MAX_FILE:
            raise DecodeError("Input exceeds 4 MiB")
        result = run(args.input.read_bytes()) + "\n"
        if args.output:
            args.output.write_text(result, encoding="utf-8")
        else:
            sys.stdout.write(result)
        return 0
    except (OSError, DecodeError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1


